package com.salim.money

import java.io.ByteArrayOutputStream
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

/**
 * Writes a styled .xlsx (Excel, Google Sheets, WPS) without any library:
 * the workbook XML is generated by hand and zipped.
 */
object XlsxReport {
    // style ids = index into cellXfs
    private const val TITLE = 1
    private const val SUB = 2
    private const val HEAD = 3
    private const val TEXT = 4
    private const val MONEY = 5
    private const val INC = 6
    private const val EXP = 7
    private const val TOTAL_L = 8
    private const val TOTAL_M = 9
    private const val PCT = 10
    private const val LABEL = 11
    private const val BIG = 12
    private const val INT = 13

    private class Sheet(val name: String) {
        val rows = sortedMapOf<Int, MutableMap<Int, Pair<Any?, Int>>>()
        val widths = mutableListOf<Double>()
        val merges = mutableListOf<String>()
        var freeze = 0
        fun set(r: Int, c: Int, v: Any?, s: Int) { rows.getOrPut(r) { sortedMapOf() }[c] = v to s }
        fun merge(r: Int, c1: Int, c2: Int, v: Any?, s: Int) {
            for (c in c1..c2) set(r, c, if (c == c1) v else null, s)
            merges += "${ref(r, c1)}:${ref(r, c2)}"
        }
    }

    private fun col(c: Int): String {
        var n = c
        val sb = StringBuilder()
        while (n > 0) { sb.insert(0, 'A' + (n - 1) % 26); n = (n - 1) / 26 }
        return sb.toString()
    }

    private fun ref(r: Int, c: Int) = "${col(c)}$r"

    private fun esc(s: String) = s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        .replace("\"", "&quot;").filter { it == '\n' || it == '\t' || it >= ' ' }

    fun build(d: ReportData): ByteArray {
        val sheets = listOf(summary(d), entries(d))
        val out = ByteArrayOutputStream()
        ZipOutputStream(out).use { zip ->
            fun put(name: String, body: String) {
                zip.putNextEntry(ZipEntry(name))
                zip.write(body.toByteArray(Charsets.UTF_8))
                zip.closeEntry()
            }
            put("[Content_Types].xml", contentTypes(sheets.size))
            put("_rels/.rels", ROOT_RELS)
            put("xl/workbook.xml", workbook(sheets))
            put("xl/_rels/workbook.xml.rels", workbookRels(sheets.size))
            put("xl/styles.xml", styles(d.decimals))
            sheets.forEachIndexed { i, s -> put("xl/worksheets/sheet${i + 1}.xml", sheetXml(s)) }
        }
        return out.toByteArray()
    }

    private fun summary(d: ReportData): Sheet {
        val s = Sheet("Summary")
        s.widths += listOf(2.0, 30.0, 18.0, 14.0, 10.0, 18.0)
        s.merge(2, 2, 6, d.title, TITLE)
        s.merge(3, 2, 6, "Income & Expense Report • ${d.periodLabel} • amounts in ${d.currency}", SUB)

        var r = 5
        listOf(
            "Total income" to d.income, "My expenses" to d.expense, "Savings" to d.net,
            "Average spend per day" to d.avgPerDay,
            "Company claims (period)" to d.claimTotal, "Claims still pending" to d.claimPending,
            "People owe me (today)" to d.owedToMe, "I owe people (today)" to d.iOwe,
        ).forEach { (k, v) ->
            s.set(r, 2, k, LABEL)
            s.set(r, 3, v, BIG)
            r++
        }
        s.set(r, 2, "Saved % of income", LABEL)
        s.set(r, 3, if (d.income > 0) d.savingsRate else null, PCT)
        r += 2

        fun table(title: String, rows: List<ReportData.Row>, total: Double) {
            s.set(r, 2, title, HEAD); s.set(r, 3, "Amount", HEAD); s.set(r, 4, "Share", HEAD)
            s.set(r, 5, "Entries", HEAD); s.set(r, 6, "Budget", HEAD)
            r++
            rows.forEach { x ->
                s.set(r, 2, "${x.category.emoji} ${x.category.name}", TEXT)
                s.set(r, 3, x.amount, MONEY)
                s.set(r, 4, x.share, PCT)
                s.set(r, 5, x.count.toDouble(), INT)
                s.set(r, 6, x.budget, MONEY)
                r++
            }
            s.set(r, 2, "Total", TOTAL_L); s.set(r, 3, total, TOTAL_M)
            s.set(r, 4, null, TOTAL_L); s.set(r, 5, null, TOTAL_L); s.set(r, 6, null, TOTAL_L)
            r += 2
        }
        if (d.expenseRows.isNotEmpty()) table("Expense category", d.expenseRows, d.expense)
        if (d.incomeRows.isNotEmpty()) table("Income source", d.incomeRows, d.income)

        if (d.byMethod.isNotEmpty()) {
            s.set(r, 2, "Paid with", HEAD); s.set(r, 3, "Amount", HEAD); s.set(r, 4, "Share", HEAD)
            r++
            d.byMethod.forEach { (k, v) ->
                s.set(r, 2, k, TEXT); s.set(r, 3, v, MONEY); s.set(r, 4, if (d.expense > 0) v / d.expense else 0.0, PCT)
                r++
            }
            r++
        }

        if (d.claims.isNotEmpty()) {
            s.set(r, 2, "Company claim", HEAD); s.set(r, 3, "Amount", HEAD); s.set(r, 4, "Date", HEAD)
            s.merge(r, 5, 6, "Status", HEAD)
            r++
            d.claims.forEach { t ->
                val c = d.cat(t.categoryId)
                s.set(r, 2, "${c.emoji} ${t.note.ifBlank { c.name }}", TEXT)
                s.set(r, 3, t.amount, MONEY)
                s.set(r, 4, t.date.format(SHORT_DATE), TEXT)
                s.merge(r, 5, 6, t.reimbursedOn?.let { "Received ${it.format(SHORT_DATE)}" } ?: "Pending", TEXT)
                r++
            }
            s.set(r, 2, "Total (pending ${"%,.${d.decimals}f".format(java.util.Locale.US, d.claimPending)})", TOTAL_L)
            s.set(r, 3, d.claimTotal, TOTAL_M)
            for (c in 4..6) s.set(r, c, null, TOTAL_L)
            r += 2
        }

        if (d.people.isNotEmpty()) {
            s.set(r, 2, "Person (loans)", HEAD); s.set(r, 3, "Amount", HEAD); s.merge(r, 4, 6, "Status", HEAD)
            r++
            d.people.forEach { (name, bal) ->
                s.set(r, 2, name, TEXT); s.set(r, 3, kotlin.math.abs(bal), MONEY)
                s.merge(r, 4, 6, if (bal > 0) "Owes me" else "I owe", TEXT)
                r++
            }
            r++
        }

        val months = d.months
        if (months.size > 1) {
            s.set(r, 2, "Month", HEAD); s.set(r, 3, "Income", HEAD); s.set(r, 4, "Expense", HEAD)
            s.set(r, 5, "", HEAD); s.set(r, 6, "Savings", HEAD)
            r++
            months.forEach { (m, inc, exp) ->
                s.set(r, 2, m.format(MONTH), TEXT); s.set(r, 3, inc, INC); s.merge(r, 4, 5, exp, EXP)
                s.set(r, 6, inc - exp, MONEY)
                r++
            }
        }
        return s
    }

    private fun entries(d: ReportData): Sheet {
        val s = Sheet("Entries")
        s.widths += listOf(2.0, 13.0, 20.0, 22.0, 32.0, 12.0, 15.0)
        s.merge(2, 2, 7, "${d.title} – all entries", TITLE)
        s.merge(3, 2, 7, d.periodLabel, SUB)
        listOf("Date", "Type", "Category", "Note", "Paid with", "Amount").forEachIndexed { i, h -> s.set(5, i + 2, h, HEAD) }
        s.freeze = 5
        var r = 6
        d.txns.forEach { t ->
            val inc = t.kind == Kind.INCOME
            val c = d.cat(t.categoryId)
            s.set(r, 2, t.date.format(SHORT_DATE), TEXT)
            s.set(
                r, 3,
                when {
                    inc -> "Income"
                    t.isClaim -> if (t.reimbursedOn != null) "Company (paid back)" else "Company (pending)"
                    else -> "Expense"
                },
                TEXT,
            )
            s.set(r, 4, "${c.emoji} ${c.name}", TEXT)
            s.set(r, 5, t.note, TEXT)
            s.set(r, 6, t.method, TEXT)
            s.set(r, 7, if (inc) t.amount else -t.amount, if (inc) INC else EXP)
            r++
        }
        s.merge(r, 2, 6, "Savings (income − my expenses)", TOTAL_L)
        s.set(r, 7, d.net, TOTAL_M)
        return s
    }

    // ------------------------------------------------------------------ xml

    private fun sheetXml(s: Sheet): String {
        val sb = StringBuilder()
        sb.append("""<?xml version="1.0" encoding="UTF-8" standalone="yes"?>""")
        sb.append("""<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">""")
        sb.append("<sheetViews><sheetView workbookViewId=\"0\" showGridLines=\"0\">")
        if (s.freeze > 0) {
            sb.append("<pane ySplit=\"${s.freeze}\" topLeftCell=\"A${s.freeze + 1}\" activePane=\"bottomLeft\" state=\"frozen\"/>")
        }
        sb.append("</sheetView></sheetViews>")
        sb.append("<sheetFormatPr defaultRowHeight=\"18\"/>")
        if (s.widths.isNotEmpty()) {
            sb.append("<cols>")
            s.widths.forEachIndexed { i, w -> sb.append("<col min=\"${i + 1}\" max=\"${i + 1}\" width=\"$w\" customWidth=\"1\"/>") }
            sb.append("</cols>")
        }
        sb.append("<sheetData>")
        s.rows.forEach { (r, cells) ->
            val ht = when (cells.values.firstOrNull()?.second) { TITLE -> " ht=\"30\" customHeight=\"1\""; HEAD -> " ht=\"22\" customHeight=\"1\""; else -> "" }
            sb.append("<row r=\"$r\"$ht>")
            cells.forEach { (c, cell) ->
                val (v, st) = cell
                val a = ref(r, c)
                when (v) {
                    null -> sb.append("<c r=\"$a\" s=\"$st\"/>")
                    is Number -> sb.append("<c r=\"$a\" s=\"$st\"><v>${v.toDouble()}</v></c>")
                    else -> sb.append("<c r=\"$a\" s=\"$st\" t=\"inlineStr\"><is><t xml:space=\"preserve\">${esc(v.toString())}</t></is></c>")
                }
            }
            sb.append("</row>")
        }
        sb.append("</sheetData>")
        if (s.merges.isNotEmpty()) {
            sb.append("<mergeCells count=\"${s.merges.size}\">")
            s.merges.forEach { sb.append("<mergeCell ref=\"$it\"/>") }
            sb.append("</mergeCells>")
        }
        sb.append("<pageMargins left=\"0.5\" right=\"0.5\" top=\"0.6\" bottom=\"0.6\" header=\"0.3\" footer=\"0.3\"/>")
        sb.append("<pageSetup paperSize=\"9\" orientation=\"portrait\" fitToWidth=\"1\" fitToHeight=\"0\"/>")
        sb.append("</worksheet>")
        return sb.toString()
    }

    private fun styles(decimals: Int): String {
        val zeros = if (decimals > 0) "." + "0".repeat(decimals) else ""
        val fmt = "#,##0$zeros"
        return """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<numFmts count="3">
<numFmt numFmtId="164" formatCode="$fmt"/>
<numFmt numFmtId="165" formatCode="0.0%"/>
<numFmt numFmtId="166" formatCode="+$fmt;-$fmt;0"/>
</numFmts>
<fonts count="8">
<font><sz val="10"/><name val="Calibri"/></font>
<font><b/><sz val="18"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font>
<font><sz val="10"/><color rgb="FF6B7280"/><name val="Calibri"/></font>
<font><b/><sz val="10"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font>
<font><sz val="10"/><color rgb="FF047857"/><name val="Calibri"/></font>
<font><sz val="10"/><color rgb="FFBE123C"/><name val="Calibri"/></font>
<font><b/><sz val="11"/><color rgb="FF312E81"/><name val="Calibri"/></font>
<font><b/><sz val="13"/><color rgb="FF111827"/><name val="Calibri"/></font>
</fonts>
<fills count="6">
<fill><patternFill patternType="none"/></fill>
<fill><patternFill patternType="gray125"/></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FF4F46E5"/><bgColor indexed="64"/></patternFill></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FF6D28D9"/><bgColor indexed="64"/></patternFill></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FFE0E7FF"/><bgColor indexed="64"/></patternFill></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FFF3F4FB"/><bgColor indexed="64"/></patternFill></fill>
</fills>
<borders count="2">
<border><left/><right/><top/><bottom/><diagonal/></border>
<border><left/><right/><top/><bottom style="thin"><color rgb="FFE5E7EB"/></bottom><diagonal/></border>
</borders>
<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
<cellXfs count="14">
<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>
<xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1" applyAlignment="1"><alignment vertical="center" indent="1"/></xf>
<xf numFmtId="0" fontId="2" fillId="0" borderId="0" xfId="0" applyFont="1"/>
<xf numFmtId="0" fontId="3" fillId="3" borderId="0" xfId="0" applyFont="1" applyFill="1" applyAlignment="1"><alignment vertical="center"/></xf>
<xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1"/>
<xf numFmtId="164" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1"/>
<xf numFmtId="166" fontId="4" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyBorder="1"/>
<xf numFmtId="166" fontId="5" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyBorder="1"/>
<xf numFmtId="0" fontId="6" fillId="4" borderId="0" xfId="0" applyFont="1" applyFill="1"/>
<xf numFmtId="164" fontId="6" fillId="4" borderId="0" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1"/>
<xf numFmtId="165" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1"/>
<xf numFmtId="0" fontId="2" fillId="5" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1"/>
<xf numFmtId="164" fontId="7" fillId="5" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/>
<xf numFmtId="1" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1"/>
</cellXfs>
<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
</styleSheet>"""
    }

    private fun contentTypes(n: Int): String {
        val sheets = (1..n).joinToString("") {
            """<Override PartName="/xl/worksheets/sheet$it.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>"""
        }
        return """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
<Default Extension="xml" ContentType="application/xml"/>
<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>
$sheets
</Types>"""
    }

    private const val ROOT_RELS = """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
</Relationships>"""

    private fun workbook(sheets: List<Sheet>): String {
        val list = sheets.mapIndexed { i, s -> """<sheet name="${esc(s.name)}" sheetId="${i + 1}" r:id="rId${i + 1}"/>""" }.joinToString("")
        return """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
<sheets>$list</sheets>
</workbook>"""
    }

    private fun workbookRels(n: Int): String {
        val rels = (1..n).joinToString("") {
            """<Relationship Id="rId$it" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet$it.xml"/>"""
        }
        return """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
$rels
<Relationship Id="rId${n + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
</Relationships>"""
    }
}
